const board = $('Get Board Records').all();
const prop = (p, n) => (p && p.properties && p.properties[n]) ? p.properties[n] : null;
const selName = (p, n) => { const x = prop(p, n); return x && x.select ? x.select.name : ''; };
const numOf = (p, n) => { const x = prop(p, n); return (x && x.number != null) ? x.number : null; };
const relIds = (p, n) => { const x = prop(p, n); return x && Array.isArray(x.relation) ? x.relation.map(r => r.id) : []; };
const groups = [['Office','Co-working Space'],['Commercial','Retail','Showroom','Mixed-use'],['Industrial','Workshop','Factory','Land'],['Residential','Compound','Hospitality']];
const compatible = (a, b) => { if (!a || !b) return false; if (a === b) return true; for (const g of groups) { if (g.indexOf(a) >= 0 && g.indexOf(b) >= 0) return true; } return false; };
const rank = { 'Excellent': 4, 'Good': 3, 'Fair': 2, 'Poor': 1 };
const demands = [];
const supplies = [];
for (const it of board) {
  const p = it.json; const rt = selName(p, 'Record Type');
  if (rt === 'Demand - Client Request') demands.push(p);
  else if (rt === 'Supply - For Rent' || rt === 'Supply - For Sale') supplies.push(p);
}
const matchable = ['New','Need Verification','Matching','Approved for RFQ'];
const out = [];
for (const dem of demands) {
  const status = selName(dem, 'Status');
  if (matchable.indexOf(status) < 0) continue;
  if (relIds(dem, '\uD83D\uDD17 Matched Supply').length > 0) continue;
  const demCity = selName(dem, 'City');
  const demCat = selName(dem, 'Property Category');
  const demSize = numOf(dem, 'Size sqm');
  const demBudget = numOf(dem, 'Budget / Price');
  if (!demCity || !demCat) continue;
  const matches = [];
  let best = 'Fair';
  for (const sup of supplies) {
    const supStatus = selName(sup, 'Status');
    if (supStatus === 'Archived' || supStatus === 'Closed Lost' || supStatus === 'Closed Won') continue;
    if (selName(sup, 'City') !== demCity) continue;
    if (!compatible(demCat, selName(sup, 'Property Category'))) continue;
    const supSize = numOf(sup, 'Size sqm');
    const supPrice = numOf(sup, 'Budget / Price');
    const sizeOk = (demSize && supSize) ? (supSize >= demSize * 0.7 && supSize <= demSize * 1.5) : null;
    const budgetOk = (demBudget && supPrice) ? (supPrice <= demBudget * 1.1) : null;
    if (sizeOk === false || budgetOk === false) continue;
    let score = 'Fair';
    if (sizeOk === true && budgetOk === true) score = 'Excellent';
    else if (sizeOk === true || budgetOk === true) score = 'Good';
    matches.push(sup.id);
    if (rank[score] > rank[best]) best = score;
  }
  if (matches.length === 0) continue;
  const newStatus = (status === 'Approved for RFQ') ? 'Approved for RFQ' : 'Matched';
  out.push({ json: { demandPageId: dem.id, matchedSupplyIds: matches, matchScore: best, newStatus, matchCount: matches.length } });
}
return out;
